export const ENTREPRENEURSHIP_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu wirausaha",q:"'Wirausaha' (entrepreneur) adalah orang yang...",options:["Melihat kebutuhan/masalah orang lain, lalu membuat & menjual produk atau jasa untuk memenuhinya, sambil menanggung risikonya","Bekerja sebagai pegawai bergaji tetap di perusahaan orang lain tanpa menanggung risiko usaha yang dijalankan sendiri","Hanya menabung uang di bank dan menunggu bunganya bertambah tanpa membuat atau menjual barang, dan dianggap cara paling aman memperoleh uang"],answer:0,explain:"Inti kewirausahaan: menciptakan nilai untuk orang lain lewat usaha sendiri, & menanggung risiko untung-rugi.",hint:"Membuat & menjual sesuatu sendiri, atau digaji orang lain?"},
{n:2,type:"mcq",micro:"Ide usaha dari masalah",q:"Ide usaha yang baik biasanya berawal dari...",options:["Meniru persis usaha milik temanmu tanpa mengubah apa-apa; usaha yang laku aman ditiru","Sebuah masalah atau kebutuhan nyata yang dialami orang & belum terpenuhi dengan baik","Barang yang paling mahal biaya pembuatannya; produk mahal dianggap bagus oleh banyak orang"],answer:1,explain:"Usaha bertahan karena menyelesaikan masalah orang. 'Apa yang menyusahkan orang & bisa kubantu?' adalah pertanyaan awal.",hint:"Kenapa orang mau membayar untuk sesuatu?"},
{n:3,type:"mcq",micro:"Pelanggan",q:"'Pelanggan' adalah...",options:["Orang yang membuat produk di pabrik besar di luar kota","Pesaing usahamu yang menjual barang serupa di dekat sekolah dan kantin sebelah","Orang yang membutuhkan & bersedia membayar untuk produk/jasamu"],answer:2,explain:"Tanpa orang yang mau membayar, sebuah ide belum menjadi usaha. Kenali siapa pelangganmu.",hint:"Siapa yang akan mengeluarkan uang untuk yang kamu jual?"},
{n:4,type:"mcq",micro:"Produk vs jasa",q:"Menjual kue = produk (barang). Memberi les = jasa. Keduanya...",options:["Bisa menjadi dasar usaha — sama-sama menciptakan nilai yang orang mau bayar","Bukan usaha; tidak memakai modal sendiri dan tidak menghasilkan","Butuh modal besar, jadi tak cocok dimulai oleh pelajar yang masih bersekolah"],answer:0,explain:"Usaha bisa menjual barang, jasa, atau keduanya. Jasa sering butuh modal awal lebih kecil.",hint:"Apakah les matematika bisa jadi usaha?"},
{n:5,type:"mcq",micro:"Modal awal",q:"'Modal awal' adalah...",options:["Pajak yang kamu bayar kepada negara setiap bulan dari hasil penjualanmu kepada pelanggan tetap dan pelanggan baru","Uang atau sumber daya yang kamu keluarkan di awal untuk memulai usaha (bahan, alat, kemasan)","Untung yang kamu dapat setelah menjual semua barang dagangan pada akhir pekan itu"],answer:1,explain:"Sebagian usaha butuh modal kecil (jasa), sebagian lebih besar (barang). Hitung modal sebelum mulai.",hint:"Apa yang harus kamu beli/siapkan sebelum bisa berjualan?"},
{n:6,type:"mcq",micro:"Pendapatan (omzet)",q:"'Pendapatan' (omzet) sebuah usaha adalah...",options:["Untung bersih yang tersisa setelah semua biaya usaha dibayarkan","Modal awal yang kamu keluarkan sebelum mulai berjualan kepada pelanggan","Total uang yang masuk dari penjualan sebelum dikurangi biaya apa pun"],answer:2,explain:"Pendapatan besar belum berarti untung besar — biaya belum dikurangi.",hint:"Semua uang penjualan yang masuk, sebelum atau sesudah biaya?"},
{n:7,type:"mcq",micro:"Biaya",q:"'Biaya' sebuah usaha adalah...",options:["Semua pengeluaran untuk menjalankan usaha: bahan, kemasan, transport, sewa, listrik, dll.","Uang yang kamu simpan di celengan atau di rekening bank setelah usaha berjalan selama beberapa bulan","Hadiah atau pemberian cuma-cuma dari pelanggan yang merasa puas dengan barang atau layanan yang kamu jual"],answer:0,explain:"Menghitung SEMUA biaya (bukan hanya bahan) penting untuk tahu untung sebenarnya.",hint:"Apa saja yang kamu keluarkan uang untuknya agar usaha berjalan?"},
{n:8,type:"mcq",micro:"Untung (laba)",q:"'Untung' (laba) sebuah usaha dihitung dengan...",options:["Hanya menghitung pendapatan","Pendapatan − semua biaya","Pendapatan + biaya"],answer:1,explain:"Untung = pendapatan − biaya. Kalau hasilnya negatif, itu 'rugi'.",hint:"Uang masuk dikurangi uang keluar."},
{n:9,type:"order",micro:"Dari ide ke untung",q:"Urutkan langkah dasar menjalankan usaha kecil.",items:["Temukan masalah/kebutuhan & pikirkan produk/jasa untuk memenuhinya","Hitung biaya & tetapkan harga jual","Jual ke pelanggan & catat pendapatan","Hitung untung (pendapatan − biaya) & perbaiki"],answer:[0,1,2,3],explain:"Ide → biaya & harga → jual & catat → hitung untung & perbaiki.",hint:"Kamu perlu tahu biaya sebelum menetapkan harga."},
{n:10,type:"mcq",micro:"Contoh menghitung untung",q:"Kamu menjual 10 gelas es teh seharga Rp3.000/gelas. Biaya bahan & es Rp12.000, kemasan Rp5.000. Untungmu...",options:["Rp30.000","Rp17.000","Rp30.000 − Rp17.000 = Rp13.000"],answer:2,explain:"Pendapatan Rp30.000 − total biaya Rp17.000 = untung Rp13.000.",hint:"Hitung pendapatan, hitung total biaya, kurangkan."},
{n:11,type:"tf",micro:"Pendapatan bukan untung",q:"Benar atau Salah: Kalau sebuah usaha punya pendapatan besar, itu belum tentu berarti untung besar — biaya bisa memakan sebagian besar atau seluruhnya.",answer:true,explain:"Banyak usaha 'ramai' tapi rugi karena biayanya terlalu tinggi dibanding harga jual. Pendapatan ≠ untung.",hint:"Kalau jual Rp1 juta tapi biaya Rp1,2 juta, untung atau rugi?"},
{n:12,type:"mcq",micro:"Harga jual & biaya",q:"Agar usaha tidak rugi, harga jual per unit harus...",options:["Lebih tinggi dari biaya per unit (agar ada selisih untuk menutup biaya lain & memberi untung)","Sama dengan biaya bahan baku saja, karena biaya lain seperti kemasan dan transport tak perlu dihitung","Semurah mungkin supaya laku keras, walau hasilnya tak menutup biaya bahan dan tenaga yang dipakai"],answer:0,explain:"Kalau harga ≤ biaya, tiap penjualan malah menambah kerugian.",hint:"Kalau membuat satu kue butuh Rp5.000, berapa minimal harga jualnya?"},
{n:13,type:"mcq",micro:"Nilai bagi pelanggan",q:"Pelanggan membeli produkmu karena...",options:["Kamu memaksa mereka membeli, jadi mereka tak punya pilihan lain saat itu dan terpaksa membayar","Menurut mereka, manfaat yang didapat lebih berharga daripada uang yang dikeluarkan","Mereka ingin membantumu dan merasa kasihan, bukan butuh barang yang kamu jual"],answer:1,explain:"Usaha berkelanjutan memberi nilai nyata: pelanggan merasa 'ini sepadan atau lebih'.",hint:"Kapan kamu rela membayar untuk sesuatu?"},
{n:14,type:"tf",micro:"Wirausaha menanggung risiko",q:"Benar atau Salah: Wirausaha dijamin mendapat 'gaji' tetap tiap bulan persis seperti pegawai, tanpa risiko rugi.",answer:false,explain:"Sebaliknya, wirausaha justru menanggung risiko — bisa untung besar, bisa juga rugi atau tidak dibayar sama sekali. Potensi untung lebih besar datang bersama risiko lebih besar.",hint:"Apakah wirausaha dijamin mendapat 'gaji' tiap bulan?"},
{n:15,type:"mcq",micro:"Mulai kecil",q:"Cara paling aman menguji ide usaha:",options:["Langsung berutang dalam jumlah besar untuk produksi besar-besaran; ide yang bagus segera laku keras","Menunggu sampai produknya sempurna sebelum menjual kepada orang lain, walau butuh waktu bertahun-tahun","Mulai kecil & murah (sedikit produk, lingkungan terdekat), lihat responnya, baru perbesar kalau berhasil"],answer:2,explain:"Uji kecil membatasi kerugian bila ide kurang cocok & memberi pelajaran cepat.",hint:"Lebih baik rugi Rp20.000 dari 10 produk, atau rugi Rp2 juta dari 1000 produk yang tidak laku?"},
{n:16,type:"mcq",micro:"Pesaing",q:"'Pesaing' adalah usaha lain yang...",options:["Menawarkan produk/jasa serupa kepada pelanggan yang sama","Membantu usahamu dengan memberi pelanggan dan modal tambahan secara gratis","Harus dihindari dan tidak boleh diamati; usahamu bisa bangkrut kalau ada pesaing"],answer:0,explain:"Adanya pesaing menandakan ada pasar. Kamu perlu tahu apa yang membuat tawaranmu berbeda/lebih baik.",hint:"Siapa lagi yang menjual hal mirip kepada calon pelangganmu?"},
{n:17,type:"mcq",micro:"Pembukuan sederhana",q:"Mencatat setiap pemasukan & pengeluaran usaha berguna untuk...",options:["Tidak berguna untuk usaha kecil; pencatatan hanya perlu perusahaan besar","Mengetahui apakah usaha untung atau rugi, & di mana bisa hemat atau perbaiki","Membuat usaha rumit, jadi pemilik lebih baik mengandalkan ingatan"],answer:1,explain:"Tanpa catatan, kamu hanya menebak. Pembukuan sederhana pun sudah sangat membantu.",hint:"Bagaimana kamu tahu untung tanpa mencatat uang masuk & keluar?"},
{n:18,type:"mcq",micro:"Uang usaha vs uang pribadi",q:"Sebaiknya uang usaha & uang pribadi...",options:["Dicampur saja supaya mudah diambil kapan pun dibutuhkan untuk keperluan","Semua dipakai untuk jajan dulu, sisanya baru dihitung sebagai modal usaha untuk membeli bahan berikutnya","Dipisah — agar jelas berapa usaha benar-benar untung & tidak 'termakan' untuk jajan"],answer:2,explain:"Mencampur membuat kamu tidak tahu kondisi usaha & mudah menghabiskan modal tanpa sadar.",hint:"Kalau uang jualan langsung dipakai jajan, bagaimana kamu tahu untungnya?"},
{n:19,type:"mcq",micro:"Kejujuran dalam berjualan",q:"Saat menjual, wirausaha yang baik...",options:["Jujur tentang apa yang dijual (bahan, kondisi, kemampuan produk) & tidak melebih-lebihkan","Menjanjikan apa saja yang diinginkan pembeli hingga produk cepat habis laku, walau produknya tak mampu melakukannya","Menyembunyikan cacat produk dari pembeli, dan memberi tahu hanya bila ditanya berulang kali"],answer:0,explain:"Kejujuran membangun kepercayaan & pelanggan yang kembali. Bohong merusak reputasi & bisa melanggar hukum.",hint:"Apakah pelanggan akan kembali kalau merasa dibohongi?"},
{n:20,type:"open",micro:"Menghitung untung usaha kecil",q:"Kamu berjualan roti bakar di acara sekolah. Modal: kompor pinjam (gratis), roti Rp40.000, selai & keju Rp35.000, kemasan Rp15.000, gas Rp10.000. Kamu menjual 30 porsi seharga Rp5.000/porsi. Hitung: (1) total pendapatan, (2) total biaya, (3) untung/rugi, (4) untung per porsi, (5) satu ide agar untung lebih besar.",explain:"Jawaban baik menghitung pendapatan (Rp150.000), total SEMUA biaya (Rp100.000), untung (Rp50.000), untung per porsi (~Rp1.667), & memberi ide realistis untuk menaikkan untung (turunkan biaya per unit, naikkan harga lewat nilai tambah, atau jual lebih banyak).",hint:"Untung = pendapatan − semua biaya. Untung per porsi = untung ÷ jumlah porsi.",sample:"(1) Pendapatan = 30 × Rp5.000 = Rp150.000. (2) Total biaya = Rp40.000 + Rp35.000 + Rp15.000 + Rp10.000 = Rp100.000. (3) Untung = Rp150.000 − Rp100.000 = Rp50.000 (untung). (4) Untung per porsi = Rp50.000 ÷ 30 ≈ Rp1.667/porsi. (5) Ide menaikkan untung: (a) beli bahan dalam jumlah lebih besar/grosir agar biaya per porsi turun; (b) kurangi biaya kemasan dengan kemasan lebih sederhana; (c) tawarkan varian 'spesial' (mis. tambah cokelat) seharga Rp7.000 dengan tambahan biaya bahan hanya Rp1.000; (d) jual lebih banyak porsi dengan promosi di awal acara."},
{n:21,type:"classify",micro:"Biaya tetap vs biaya variabel",q:"Kelompokkan tiap biaya usaha jualan minuman ke 'Biaya tetap (tidak berubah dengan jumlah terjual)' atau 'Biaya variabel (naik saat menjual lebih banyak)'.",items:["Sewa gerobak Rp20.000/hari","Gula & teh per gelas","Sedotan & gelas plastik per porsi","Biaya cetak spanduk sekali"],groups:["Biaya tetap (tidak berubah dengan jumlah terjual)","Biaya variabel (naik saat menjual lebih banyak)"],answer:{"Biaya tetap (tidak berubah dengan jumlah terjual)":["Sewa gerobak Rp20.000/hari","Biaya cetak spanduk sekali"],"Biaya variabel (naik saat menjual lebih banyak)":["Gula & teh per gelas","Sedotan & gelas plastik per porsi"]},explain:"Biaya tetap harus dibayar berapa pun penjualan; biaya variabel bertambah tiap unit. Keduanya perlu ditutup harga jual.",hint:"Apakah biaya ini berubah kalau kamu menjual 10 vs 100 gelas?"},
{n:22,type:"mcq",micro:"Menetapkan harga: pertimbangan",q:"Saat menetapkan harga jual, pertimbangkan...",options:["Sesukamu tanpa dasar; pelanggan akan membayar berapa saja yang kamu minta","Biaya per unit, harga pesaing, nilai/manfaat bagi pelanggan, & kemampuan bayar pasar sasaran","Hanya biaya bahan; biaya lain seperti tenaga, listrik, dan kemasan tak perlu dihitung dalam menentukan harga jual"],answer:1,explain:"Harga yang baik menutup biaya + memberi untung, tapi tetap masuk akal dibanding pesaing & nilai yang dirasakan pelanggan.",hint:"Apa saja yang menentukan apakah sebuah harga 'pas'?"},
{n:23,type:"mcq",micro:"Harga terlalu murah",q:"Menetapkan harga terlalu murah (di bawah atau pas dengan biaya) berisiko...",options:["Membuat usaha sukses; penjualan murah menarik banyak pelanggan baru dan langsung untung","Tidak ada risiko; harga murah membuat pelanggan puas dan usaha tetap berjalan lancar","Usaha rugi tiap penjualan, kelelahan tanpa hasil, & pelanggan menganggap kualitasnya rendah"],answer:2,explain:"'Murah' bukan selalu strategi baik. Harga harus berkelanjutan bagi usahamu.",hint:"Apa yang terjadi kalau tiap produk yang terjual malah menambah rugi?"},
{n:24,type:"mcq",micro:"Pembeda (diferensiasi)",q:"'Pembeda' usahamu adalah...",options:["Alasan pelanggan memilihmu daripada pesaing: mis. lebih enak, lebih murah, lebih cepat, lebih ramah, lebih dekat, atau unik","Warna spanduk dan hiasan di depan lapak; itu yang paling terlihat oleh pelanggan yang lewat di jalan","Jumlah uang di kasmu pada hari itu; menunjukkan seberapa besar usaha berhasil menarik orang ke tempatmu"],answer:0,explain:"Kalau produkmu persis sama dengan pesaing tanpa pembeda, kamu hanya bisa bersaing lewat harga (sering merugikan).",hint:"Kenapa pelanggan memilih kamu, bukan penjual sebelah?"},
{n:25,type:"mcq",micro:"Menguji ide (MVP)",q:"'Versi paling sederhana' dari produk untuk diuji ke pelanggan berguna karena...",options:["Pelanggan tidak suka versi sederhana; lebih baik langsung membuat versi lengkap yang mewah","Kamu belajar apakah orang benar-benar mau membeli SEBELUM menghabiskan banyak waktu & uang membuat versi lengkap","Membuang waktu; pelanggan akan membeli apa saja yang sudah kamu siapkan dengan baik sejak awal"],answer:1,explain:"Menguji dengan versi minimal mengurangi risiko membangun sesuatu yang ternyata tidak diinginkan orang.",hint:"Lebih baik tahu ide gagal setelah 1 minggu & Rp50.000, atau setelah 6 bulan & Rp5 juta?"},
{n:26,type:"mcq",micro:"Umpan balik pelanggan",q:"Setelah menjual, menanyakan pendapat pelanggan berguna untuk...",options:["Membuat pelanggan kesal karena ditanya-tanya, sehingga mereka tak kembali ke tempat usahamu","Tidak berguna bila barangnya sudah laku terjual, karena pendapat pelanggan tak mengubah produk","Mengetahui apa yang disukai & apa yang perlu diperbaiki, sehingga produk & layanan makin cocok"],answer:2,explain:"Usaha yang tumbuh mendengarkan pelanggan & terus memperbaiki diri.",hint:"Bagaimana kamu tahu apa yang harus diperbaiki tanpa bertanya?"},
{n:27,type:"tf",micro:"Gagal adalah bagian dari belajar",q:"Benar atau Salah: Ide usaha pertama yang gagal berarti kamu tidak berbakat & sebaiknya tidak pernah mencoba berwirausaha lagi.",answer:false,explain:"Sebaliknya, ide yang tidak berhasil — kalau dijalankan skala kecil & dievaluasi — memberi pelajaran berharga. Banyak wirausaha sukses pernah gagal beberapa kali: kuncinya gagal kecil, belajar, perbaiki.",hint:"Apakah percobaan pertama yang gagal berarti tidak boleh mencoba lagi?"},
{n:28,type:"mcq",micro:"Arus kas vs untung",q:"Sebuah usaha bisa 'untung di atas kertas' tapi kehabisan uang tunai karena...",options:["Untung tercatat, tapi uangnya belum diterima (pelanggan berutang) atau sudah dipakai beli stok — sehingga tidak ada tunai untuk kebutuhan mendesak","Untung berarti banyak uang tunai di tangan, sehingga usaha yang untung tak mungkin kehabisan uang, tanpa dicek lagi, apalagi bagi usaha kecil","Itu tak mungkin terjadi karena angka untung dan jumlah uang tunai sama persis pada setiap waktu, jadi tak perlu dua catatan terpisah di buku usaha"],answer:0,explain:"'Arus kas' (uang tunai yang benar-benar ada) berbeda dari 'untung'. Usaha butuh keduanya sehat.",hint:"Kalau semua untungmu berupa piutang (belum dibayar), bisakah kamu membeli bahan besok?"},
{n:29,type:"mcq",micro:"Menghitung modal balik (BEP)",q:"'Titik impas' (balik modal) adalah...",options:["Saat untung paling besar; penjualan sudah melebihi semua biaya usaha dan modal awal kembali","Jumlah penjualan di mana total pendapatan = total biaya (belum untung, belum rugi)","Saat usaha ditutup; modal awal sudah habis dan tak ada pelanggan lagi"],answer:1,explain:"Mengetahui titik impas membantu menargetkan: 'aku harus menjual minimal X agar tidak rugi'.",hint:"Berapa yang harus terjual agar semua biaya tertutup pas?"},
{n:30,type:"order",micro:"Menghitung titik impas sederhana",q:"Urutkan langkah menghitung berapa unit yang harus dijual untuk balik modal.",items:["Hitung total biaya tetap (mis. sewa, spanduk)","Hitung untung per unit = harga jual − biaya variabel per unit","Bagi total biaya tetap dengan untung per unit","Hasilnya = jumlah unit minimal agar tidak rugi"],answer:[0,1,2,3],explain:"Biaya tetap ÷ (harga − biaya variabel per unit) = unit titik impas.",hint:"Tiap unit memberi 'untung per unit' untuk menutup biaya tetap. Berapa unit dibutuhkan?"},
{n:31,type:"mcq",micro:"Segmen pelanggan",q:"'Menentukan pelanggan sasaran' berarti...",options:["Mencoba menjual ke banyak orang sekaligus tanpa membeda-bedakan; makin banyak calon pembeli makin besar penjualan di sekolah dan di lingkungan rumah","Tak peduli siapa pembelinya; produk bagus dibeli siapa saja tanpa perlu dirancang khusus, kualitas berbicara sendiri","Memilih kelompok tertentu yang paling butuh produkmu (mis. teman sekelas yang lapar saat istirahat) & merancang tawaran untuk mereka"],answer:2,explain:"Fokus pada sasaran yang jelas membuat produk, harga, & promosi lebih tepat daripada 'untuk semua orang'.",hint:"Siapa yang paling mungkin & paling butuh membeli produkmu?"},
{n:32,type:"mcq",micro:"Promosi jujur",q:"Cara mempromosikan usaha kecil dengan baik:",options:["Beri tahu orang apa yang kamu jual, apa manfaatnya, & di mana/kapan — dengan jujur; dari mulut ke mulut, poster, atau media sosial","Membuat klaim berlebihan yang tidak bisa dibuktikan, misalnya 'terbaik sedunia' atau 'dijamin sembuh' di setiap poster","Menjelekkan usaha pesaing dengan cerita bohong dan membuat pembeli pindah dan hanya membeli dari tempat usahamu saja"],answer:0,explain:"Promosi yang jujur & jelas membangun kepercayaan. Klaim palsu merusak reputasi & bisa melanggar aturan.",hint:"Apa yang perlu diketahui calon pembeli, & haruskah itu benar?"},
{n:33,type:"tf",micro:"Waktu adalah biaya",q:"Benar atau Salah: Waktu yang kamu curahkan untuk usaha juga 'biaya' — kalau untungnya sangat kecil dibanding jam kerja & mengorbankan sekolah, ide itu perlu diperbaiki atau ditinjau ulang.",answer:true,explain:"Menghitung untung per jam membantu menilai apakah usaha sepadan dengan waktu & tenaga.",hint:"Kalau usaha memberi untung Rp10.000 untuk 10 jam kerja, apakah itu sepadan?"},
{n:34,type:"mcq",micro:"Kualitas & konsistensi",q:"Pelanggan kembali & merekomendasikan usaha yang...",options:["Berganti-ganti rasa dan cara melayani tanpa alasan, jadi pelanggan tak bosan","Menjaga kualitas & konsisten (rasa, layanan, ketepatan) dari waktu ke waktu","Bagus saat pertama dibuka, lalu asal-asalan setelah pelanggan datang sendiri"],answer:1,explain:"Kepercayaan dibangun dari pengalaman yang bisa diandalkan berulang kali.",hint:"Apakah kamu kembali ke warung yang rasanya berubah-ubah & pelayanannya tak menentu?"},
{n:35,type:"mcq",micro:"Menabung untuk usaha",q:"Sebagian untung usaha sebaiknya...",options:["Dihabiskan seluruhnya untuk jajan dan bersenang-senang; keuntungan memang hadiah bagi pemilik usahanya yang bekerja keras sepanjang minggu","Disimpan begitu saja di dompet tanpa rencana, sulit diketahui kapan dan untuk apa akan dipakai nanti oleh pemiliknya","Disisihkan kembali (diinvestasikan) untuk membeli bahan berikutnya, alat lebih baik, atau memperbesar usaha — tidak semua dihabiskan"],answer:2,explain:"Usaha tumbuh kalau sebagian untung 'diputar' kembali. Menghabiskan semua untung membuat usaha jalan di tempat atau mengecil.",hint:"Dari mana modal untuk produksi berikutnya kalau semua untung habis?"},
{n:36,type:"mcq",micro:"Legal & izin (gagasan)",q:"Untuk usaha yang lebih besar, mematuhi aturan (izin, keamanan pangan, pajak) penting karena...",options:["Melindungi pelanggan & usahamu, membangun kepercayaan, & menghindari sanksi","Hanya menyulitkan usaha tanpa manfaat, jadi dihindari selama usaha kecil","Aturan bisa diabaikan selama pembeli tak mengeluh dan petugas jarang datang"],answer:0,explain:"Usaha yang taat aturan lebih tahan lama & tepercaya. Untuk usaha pelajar kecil, ini berarti mis. menjaga kebersihan makanan.",hint:"Kenapa ada aturan kebersihan untuk penjual makanan?"},
{n:37,type:"tf",micro:"Ide bukan segalanya",q:"Benar atau Salah: Punya ide yang 'brilian' sudah cukup untuk berhasil; cara menjalankannya (membuat, menjual, melayani, memperbaiki) hampir tidak berpengaruh.",answer:false,explain:"Sebaliknya, eksekusi yang baik biasanya lebih menentukan keberhasilan daripada sekadar ide. Banyak orang punya ide bagus; sedikit yang menjalankannya dengan tekun.",hint:"Ide bagus yang tidak dikerjakan vs ide biasa yang dikerjakan sungguh-sungguh — mana yang menghasilkan?"},
{n:38,type:"mcq",micro:"Skala & kapasitas",q:"Sebelum menerima pesanan besar, wirausaha perlu memastikan...",options:["Menolak pesanan besar; pesanan dalam jumlah banyak merepotkan, menghabiskan waktu belajar, dan jarang menguntungkan","Ia mampu memproduksi jumlah itu tepat waktu dengan kualitas terjaga (bahan, tenaga, alat cukup)","Menerima pesanan tanpa berpikir panjang; pesanan besar berarti untung besar tanpa risiko"],answer:1,explain:"Menerima pesanan yang tidak bisa dipenuhi merusak reputasi. Kenali kapasitasmu.",hint:"Apa yang terjadi kalau kamu janji 200 kue tapi hanya bisa membuat 50?"},
{n:39,type:"mcq",micro:"Kerja sama & pembagian",q:"Kalau berwirausaha bersama teman, hal yang bijak disepakati di awal:",options:["Tidak perlu membahas apa-apa di awal; pertemanan yang baik membuat semuanya beres sendiri nanti","Semua untung milik yang punya ide saja, sedangkan teman lain cukup membantu tanpa mendapat bagian sedikit pun","Pembagian tugas, pembagian modal, pembagian untung/rugi, & cara mengambil keputusan — sebaiknya tertulis"],answer:2,explain:"Kesepakatan yang jelas di awal mencegah pertengkaran saat usaha mulai menghasilkan (atau merugi).",hint:"Apa yang bisa jadi sumber pertengkaran kalau tidak dibicarakan sejak awal?"},
{n:40,type:"open",micro:"Merancang uji ide usaha",q:"Kamu ingin menjual 'paket alat tulis darurat' (pulpen, pensil, penghapus, kertas) untuk teman yang lupa membawa. Rancang uji ide skala kecil: (1) pelanggan sasaran & masalahnya, (2) versi paling sederhana yang bisa dijual minggu ini, (3) modal & harga jual (beserta alasan), (4) unit untuk balik modal, (5) 2 pertanyaan umpan balik untuk pembeli, (6) tanda ide layak dilanjutkan atau dihentikan.",explain:"Rancangan baik menyebut pelanggan & masalah yang jelas, versi minimal yang benar-benar bisa dibuat cepat, modal & harga dengan alasan (menutup biaya + untung + masuk akal bagi pembeli), perhitungan balik modal, pertanyaan umpan balik yang berguna, & kriteria lanjut/berhenti yang konkret.",hint:"Versi sederhana + modal & harga beralasan + titik impas + pertanyaan umpan balik + kriteria keputusan yang bisa diukur.",sample:"(1) Pelanggan: teman sekelas/seangkatan yang sering lupa bawa alat tulis, terutama saat ulangan; masalah: panik meminjam & mengganggu orang lain. (2) Versi sederhana: 10 paket berisi 1 pulpen + 1 pensil + 1 penghapus kecil + 5 lembar kertas, dimasukkan kantong plastik klip. (3) Modal: beli grosir — pulpen Rp1.500, pensil Rp1.000, penghapus Rp1.000, kertas Rp500, plastik Rp200 = Rp4.200/paket × 10 = Rp42.000. Harga jual Rp6.000/paket (untung Rp1.800/paket) — masih murah dibanding harus keluar kelas membeli, & lebih praktis. (4) Balik modal: biaya tetap ~0 (tidak ada sewa), jadi tiap paket langsung menutup biayanya sendiri; secara total aku balik modal Rp42.000 setelah menjual 7 paket (7 × Rp6.000 = Rp42.000). (5) Pertanyaan umpan balik: 'Apakah harganya terasa pas, mahal, atau murah?' & 'Isi apa yang kurang atau berlebih menurutmu?' (6) Layak dilanjutkan kalau 10 paket habis dalam 1–2 minggu & beberapa orang bertanya kapan restock; dihentikan/diubah kalau setelah 3 minggu masih tersisa banyak & umpan baliknya 'tidak butuh' atau 'terlalu mahal'."},
{n:41,type:"mcq",micro:"Hitung untung per unit",q:"Harga jual gelang Rp15.000. Biaya bahan per gelang Rp6.000. Biaya variabel lain (kemasan) Rp1.000/gelang. Untung per gelang...",options:["Rp8.000","Rp9.000","Rp15.000"],answer:0,explain:"Rp15.000 − Rp6.000 − Rp1.000 = Rp8.000 per gelang (sebelum biaya tetap).",hint:"Harga jual − semua biaya variabel per unit."},
{n:42,type:"mcq",micro:"Hitung titik impas",q:"Untung per unit Rp8.000. Biaya tetap (stan bazar) Rp40.000. Berapa gelang harus terjual untuk balik modal?",options:["40 gelang","5 gelang","8 gelang"],answer:1,explain:"Rp40.000 ÷ Rp8.000 = 5 gelang. Gelang ke-6 dan seterusnya mulai memberi untung bersih.",hint:"Biaya tetap ÷ untung per unit."},
{n:43,type:"mcq",micro:"Untung total",q:"Kalau kamu menjual 12 gelang (untung per unit Rp8.000, biaya tetap Rp40.000), untung bersih totalmu...",options:["12 × Rp8.000 = Rp96.000","Rp40.000","(12 × Rp8.000) − Rp40.000 = Rp56.000"],answer:2,explain:"Total kontribusi Rp96.000 − biaya tetap Rp40.000 = untung bersih Rp56.000.",hint:"Total (untung per unit × jumlah) lalu kurangi biaya tetap."},
{n:44,type:"mcq",micro:"Menurunkan biaya per unit",q:"Cara umum menurunkan biaya per unit:",options:["Beli bahan dalam jumlah lebih besar (grosir), kurangi bahan yang tidak menambah nilai, & kurangi pemborosan/sisa","Menaikkan harga jual ke pelanggan, padahal itu menambah pendapatan per unit dan tak mengurangi biaya pembuatannya sendiri sedikit pun","Menambah kemasan mewah pada tiap produk, padahal itu justru membuat biaya per unit makin besar dan harga naik"],answer:0,explain:"Biaya per unit turun lewat pembelian efisien & mengurangi pemborosan — bukan dengan mengorbankan kualitas inti.",hint:"Apa yang membuat biaya membuat satu produk lebih murah?"},
{n:45,type:"order",micro:"Siklus perbaikan usaha",q:"Urutkan siklus memperbaiki usaha kecil berdasarkan data.",items:["Jual & catat pendapatan, biaya, & jumlah terjual","Hitung untung & bandingkan dengan targetmu","Cari penyebab: harga? biaya? jumlah pembeli? kualitas?","Ubah SATU hal, jual lagi, & bandingkan hasilnya"],answer:[0,1,2,3],explain:"Catat → hitung & bandingkan → diagnosis → ubah satu hal & uji lagi. Mengubah satu hal per kali memudahkan tahu apa yang berpengaruh.",hint:"Bagaimana kamu tahu perubahan mana yang membantu kalau mengubah banyak hal sekaligus?"},
{n:46,type:"mcq",micro:"Menaikkan harga: kapan",q:"Menaikkan harga bisa masuk akal kalau...",options:["Tak masuk akal; pelanggan pergi begitu harga barang dinaikkan sedikit saja, apalagi saat sepi","Produk sering habis cepat, pelanggan bilang 'murah banget', biaya bahan naik, atau kamu menambah nilai (kualitas/layanan lebih baik)","Kamu sedang butuh uang lebih banyak minggu ini, padahal kebutuhanmu tidak berkaitan dengan nilai produk bagi pelanggan"],answer:1,explain:"Harga bukan angka mati. Naikkan bertahap saat ada alasan (permintaan tinggi, biaya naik, nilai bertambah) & amati responnya.",hint:"Tanda apa yang menunjukkan hargamu mungkin terlalu rendah?"},
{n:47,type:"mcq",micro:"Diskon & bundling",q:"Memberi diskon untuk pembelian banyak ('beli 3 lebih murah') bisa berguna karena...",options:["Menguntungkan berapa pun besarnya diskon yang diberikan; pembeli yang makin banyak menutup semua kerugian bagi penjual","Membuat pelanggan curiga, jadi diskon sebaiknya tak diberikan dalam kondisi apa saja kepada pembeli di pasar","Mendorong pelanggan membeli lebih banyak sekaligus — asal harga diskon masih di atas biaya & totalnya tetap menguntungkan"],answer:2,explain:"Bundling/diskon volume bisa menaikkan untung TOTAL meski untung per unit turun — asal hitungannya tetap positif.",hint:"Kapan menjual lebih banyak dengan untung per unit lebih kecil tetap menguntungkan?"},
{n:48,type:"mcq",micro:"Arus kas praktis",q:"Untuk menjaga arus kas usaha kecil tetap sehat:",options:["Utamakan penjualan tunai atau bayar di muka; jangan pakai semua uang untuk stok sekaligus; sisakan tunai untuk kebutuhan mendadak","Biarkan semua pelanggan berutang dulu dan dagangan tampak laris, dan tagih nanti kalau sudah banyak yang menunggak","Belikan seluruh uang usaha untuk stok sebanyak mungkin, tanpa menyisakan tunai untuk kebutuhan mendadak"],answer:0,explain:"Usaha kecil sering gagal bukan karena rugi, tapi karena kehabisan uang tunai untuk beroperasi.",hint:"Apa yang terjadi kalau semua uangmu jadi stok & tidak ada tunai untuk beli gas besok?"},
{n:49,type:"mcq",micro:"Memilih di antara ide",q:"Kamu punya 3 ide usaha. Cara memilih:",options:["Kerjakan ketiga ide sekaligus dalam waktu yang sama; yang paling berhasil langsung diketahui tanpa perlu menghitung modal dan risikonya lebih dulu","Bandingkan: seberapa nyata masalahnya, kemampuanmu membuatnya, modal & risiko, potensi untung, & kecocokan waktumu — lalu uji yang paling menjanjikan dulu","Pilih yang paling keren kedengarannya di telinga teman-temanmu tanpa menghitung modal, risiko, dan kemampuanmu sendiri; gengsi itu penting"],answer:1,explain:"Kriteria yang jelas (masalah nyata, kemampuan, modal/risiko, untung, waktu) membantu memilih; fokus pada satu dulu.",hint:"Faktor apa yang membuat satu ide lebih layak dicoba lebih dulu?"},
{n:50,type:"mcq",micro:"Pelanggan setia vs pelanggan baru",q:"Umumnya, menjaga pelanggan yang sudah ada (agar kembali)...",options:["Tidak penting, yang penting pelanggan baru; pelanggan lama sudah bosan dengan usahamu dan tak akan membeli lagi","Sama saja usahanya; pelanggan lama dan pelanggan baru membutuhkan biaya yang persis sama untuk didapat dan dilayani","Lebih murah & lebih mudah daripada terus mencari pelanggan baru — jadi layanan & kualitas yang membuat orang kembali sangat berharga"],answer:2,explain:"Pelanggan yang puas kembali lagi & merekomendasikan — 'promosi gratis' yang paling dipercaya.",hint:"Mana yang lebih hemat: melayani pelanggan lama dengan baik, atau terus berpromosi ke orang asing?"},
{n:51,type:"open",micro:"Menganalisis usaha yang merugi",q:"Temanmu berjualan minuman di sekolah selama 2 minggu & merugi. Datanya: jual 8 gelas/hari @ Rp4.000; biaya bahan Rp2.500/gelas; sewa lapak Rp15.000/hari; es & gas Rp5.000/hari. Analisis: (1) hitung untung/rugi per hari, (2) di mana masalahnya, (3) hitung berapa gelas/hari untuk balik modal pada harga sekarang, (4) beri 3 opsi perbaikan berbeda dengan konsekuensinya, (5) apa yang kamu sarankan.",explain:"Jawaban baik menghitung rugi harian (−Rp8.000), mendiagnosis DUA penyebab (margin per unit tipis + volume rendah vs biaya tetap tinggi), menghitung titik impas (~14 gelas), memberi 3 opsi berbeda (naikkan harga / potong biaya tetap / potong biaya variabel) dengan konsekuensi masing-masing, & memberi saran yang beralasan (menekan biaya lebih aman daripada menaikkan harga karena volume 8 sudah terbukti).",hint:"Untung per gelas = harga − biaya bahan. Titik impas = biaya tetap ÷ untung per gelas. Bandingkan dengan 8 gelas yang benar-benar laku.",sample:"(1) Pendapatan/hari = 8 × Rp4.000 = Rp32.000. Biaya variabel = 8 × Rp2.500 = Rp20.000. Biaya tetap/hari = Rp15.000 + Rp5.000 = Rp20.000. Total biaya = Rp40.000. Rugi = Rp32.000 − Rp40.000 = −Rp8.000/hari. (2) Masalah: untung per gelas hanya Rp4.000 − Rp2.500 = Rp1.500; untuk menutup biaya tetap Rp20.000 butuh menjual ~13–14 gelas/hari, tapi hanya laku 8. Jadi masalahnya kombinasi: untung per gelas terlalu tipis DAN jumlah pembeli terlalu sedikit untuk biaya tetap sebesar itu. (3) Titik impas = Rp20.000 ÷ Rp1.500 ≈ 13,3 → 14 gelas/hari. (4) Opsi: (a) Naikkan harga ke Rp5.000 → untung per gelas Rp2.500, titik impas turun ke 8 gelas/hari — pas dengan penjualan sekarang, tapi berisiko sebagian pembeli mundur. (b) Hilangkan sewa lapak (jual keliling/dari tas) → biaya tetap turun jadi Rp5.000, titik impas jadi ~4 gelas/hari — langsung untung, tapi lebih capek & jangkauan mungkin berkurang. (c) Turunkan biaya bahan ke Rp2.000/gelas (beli grosir, porsi pas) → untung per gelas Rp2.000, titik impas 10 gelas/hari — masih di atas penjualan sekarang. (5) Saran: gabungkan (b) + (c) — lepas sewa lapak & tekan biaya bahan; ini membuat usaha untung pada volume penjualan yang sudah terbukti (8 gelas), tanpa mempertaruhkan pelanggan lewat kenaikan harga. Setelah untung stabil & pembeli bertambah, baru pertimbangkan lapak lagi."},
{n:52,type:"mcq",micro:"Iterasi berdasarkan umpan balik",q:"Kamu mendapat umpan balik: 'Enak, tapi porsinya kekecilan.' Respons wirausaha yang baik:",options:["Uji: tambah sedikit porsi & naikkan harga tipis, atau tawarkan ukuran 'besar', lalu lihat apakah penjualan & kepuasan naik","Abaikan kritik itu; produk sudah jadi dan pelanggan terbiasa dengan porsi yang ada sekarang, itu hal biasa dan nanti mereka juga terbiasa","Marah kepada pelanggan yang berkomentar; kritik seperti itu hanya membuat penjual kehilangan semangat berjualan"],answer:0,explain:"Umpan balik adalah petunjuk perbaikan. Uji perubahan kecil & ukur dampaknya.",hint:"Apa yang kamu lakukan dengan keluhan yang sama dari beberapa pelanggan?"},
{n:53,type:"tf",micro:"Satu perubahan per kali",q:"Benar atau Salah: Saat memperbaiki usaha, mengubah satu hal pada satu waktu (harga saja, atau resep saja) memudahkanmu mengetahui perubahan mana yang benar-benar berpengaruh.",answer:true,explain:"Kalau mengubah harga, resep, & kemasan sekaligus lalu penjualan berubah, kamu tidak tahu penyebabnya. Ubah satu, ukur, lanjut.",hint:"Kalau 5 hal berubah bersamaan & hasilnya membaik, mana yang berjasa?"},
{n:54,type:"mcq",micro:"Menghargai waktu sendiri",q:"Kamu berjualan & mendapat untung bersih Rp70.000 untuk total 10 jam kerja seminggu. Untung per jam...",options:["Tidak bisa dihitung; pendapatan usaha tak menentu dan tenaga serta waktu tak punya nilai uang","Rp7.000/jam — bandingkan dengan alternatif (les, kerja lain, atau waktu belajar) untuk menilai apakah sepadan","Rp70.000/jam — angka ini hasil pembagian yang keliru, waktu kerja dikira hanya satu jam, bukan sepuluh jam seminggu"],answer:1,explain:"Rp70.000 ÷ 10 = Rp7.000/jam. Menghitung ini membantu memutuskan apakah melanjutkan, memperbaiki, atau mengganti kegiatan.",hint:"Bagi untung bersih dengan jam yang kamu curahkan."},
{n:55,type:"mcq",micro:"Reinvestasi untung",q:"Kamu untung Rp100.000 bulan ini. Keputusan yang membangun usaha:",options:["Habiskan semua Rp100.000 untuk jajan dan hiburan bersama teman; untung memang hadiah bagi pemilik usaha yang sudah bekerja keras","Simpan semuanya tanpa rencana dan jangan dipakai lagi, meskipun usaha butuh bahan dan alat yang lebih baik bagi pelanggan di sekolah","Sisihkan sebagian (mis. Rp40.000) untuk membeli alat/bahan yang menaikkan kapasitas atau kualitas, sebagian untuk tabungan usaha, sisanya boleh dinikmati"],answer:2,explain:"Reinvestasi sebagian untung membuat usaha tumbuh; menyisihkan sebagian memberi penyangga; menikmati sebagian menjaga motivasi.",hint:"Bagaimana usaha bisa membesar kalau untungnya selalu habis untuk jajan?"},
{n:56,type:"mcq",micro:"Menolak pesanan yang tidak sanggup",q:"Seseorang memesan 100 kue untuk besok, padahal kapasitasmu 30/hari. Respons profesional:",options:["Jujur: tawarkan jumlah yang sanggup kamu buat dengan kualitas terjaga, atau waktu pengerjaan yang realistis","Terima saja pesanan itu dan berharap bisa menyelesaikannya, walau kapasitas produksimu jauh di bawah jumlahnya","Terima pesanannya lalu batalkan mendadak keesokan harinya kalau tak sanggup, tanpa memberi tahu siapa pun sebelumnya"],answer:0,explain:"Menjanjikan yang tidak bisa dipenuhi merusak reputasi lebih parah daripada menolak dengan jujur.",hint:"Mana yang lebih merusak kepercayaan: menolak jujur, atau gagal memenuhi janji?"},
{n:57,type:"tf",micro:"Usaha kecil pun perlu catatan",q:"Benar atau Salah: Usaha sekecil jualan di bazar sekolah tidak perlu mencatat modal, penjualan, & biaya — cukup mengira-ngira untungnya.",answer:false,explain:"Sebaliknya, bahkan usaha kecil sebaiknya mencatat semua pemasukan & pengeluaran agar tahu untung sebenarnya & belajar mengelola. Tanpa catatan, 'untung' hanyalah perasaan.",hint:"Bagaimana kamu tahu untung tanpa mencatat uang masuk & keluar?"},
{n:58,type:"mcq",micro:"Nilai tambah",q:"'Nilai tambah' adalah cara menaikkan harga yang bisa diterima pelanggan dengan...",options:["Mengurangi isi atau ukuran produk diam-diam untuk menurunkan biaya, sambil tetap menjual dengan harga yang sama dan berharap pelanggan tak menyadarinya","Menambah manfaat nyata: kualitas lebih baik, kemasan lebih praktis, layanan antar, garansi, atau pengalaman yang lebih menyenangkan","Menaikkan harga tanpa mengubah apa-apa pada produk atau layanan, dengan harapan pelanggan tak menyadarinya, lalu menyalahkan biaya"],answer:1,explain:"Pelanggan rela membayar lebih kalau merasa mendapat lebih. Mengurangi isi diam-diam justru merusak kepercayaan.",hint:"Kenapa orang mau membayar lebih untuk produk yang 'sama' dari penjual berbeda?"},
{n:59,type:"mcq",micro:"Etika: klaim produk",q:"Kamu menjual jus & ingin menulis 'menyehatkan'. Sikap yang tepat:",options:["Tulis klaim yang membuat jusmu laku keras, termasuk 'menyembuhkan banyak penyakit' agar pembeli cepat tertarik, walau belum diuji","Tiru klaim yang dipakai pesaing tanpa memeriksa kebenarannya; kalau mereka berani menulis berarti benar dan aman dipakai","Hanya buat klaim yang benar & bisa kamu dukung (mis. 'dari buah segar, tanpa pewarna'); hindari klaim kesehatan berlebihan yang tidak terbukti"],answer:2,explain:"Klaim jujur & spesifik membangun kepercayaan; klaim kesehatan palsu bisa menyesatkan & melanggar aturan.",hint:"Bisakah kamu membuktikan setiap kata dalam iklanmu?"},
{n:60,type:"open",micro:"Rencana satu halaman usaha kecil",q:"Buat 'rencana satu halaman' untuk ide usaha pelajar pilihanmu. Isi: (1) masalah & pelanggan sasaran, (2) produk/jasa & pembedanya, (3) daftar biaya (tetap & variabel) & harga jual, (4) untung per unit & titik impas, (5) promosi jujur & tempat/waktu jualan, (6) target minggu pertama & cara tahu apakah lanjut, (7) pembagian untung (reinvestasi/tabungan/nikmati), (8) satu risiko utama & rencananya.",explain:"Rencana baik mengisi kedelapan bagian dengan konkret: masalah & pelanggan jelas, pembeda nyata, biaya dipisah tetap/variabel + harga, untung per unit & titik impas dihitung, promosi jujur & kanal jelas, target & kriteria lanjut/berhenti terukur, pembagian untung (reinvestasi diutamakan), & satu risiko dengan mitigasi yang masuk akal (produksi sesuai pesanan).",hint:"Ikuti kedelapan poin; pastikan angka biaya, harga, untung per unit, & titik impas konsisten satu sama lain.",sample:"Contoh (usaha: 'camilan sehat kiloan untuk teman yang begadang belajar'): (1) Masalah: teman yang belajar sampai malam lapar tapi malas keluar & tidak mau camilan terlalu berat/berminyak; pelanggan: teman seangkatan kelas 8–9 yang aktif belajar kelompok. (2) Produk: kantong kecil berisi campuran kacang panggang + kismis + sereal, 50 gram; pembeda: porsi pas sekali makan, tidak berminyak, bisa pesan H-1 & kuantar ke kelas. (3) Biaya variabel per kantong: kacang Rp2.000 + kismis Rp1.500 + sereal Rp1.000 + kemasan Rp500 = Rp5.000. Biaya tetap: cetak stiker label sekali Rp20.000. Harga jual: Rp8.000. (4) Untung per unit = Rp8.000 − Rp5.000 = Rp3.000. Titik impas = Rp20.000 ÷ Rp3.000 ≈ 7 kantong. (5) Promosi: cerita ke teman & grup kelas dengan jujur ('camilan buat nemenin belajar, isi kacang-kismis-sereal, Rp8.000, pesan sehari sebelum'); tempel 1 poster kecil di mading kelas; jualan diantar saat istirahat. (6) Target minggu pertama: 15 kantong. Lanjut kalau ≥12 terjual & ada yang pesan lagi; tinjau ulang kalau <8 terjual atau umpan balik 'kemahalan/tidak butuh'. (7) Pembagian untung: 50% beli bahan minggu berikutnya (reinvestasi), 25% tabungan usaha (untuk beli wadah/timbangan), 25% boleh kunikmati. (8) Risiko utama: bahan tidak habis terjual & jadi rugi. Rencana: produksi sesuai pesanan yang masuk H-1 saja (bukan menebak), & mulai dari 10 kantong, tambah hanya kalau permintaan terbukti."},
{n:61,type:"mcq",micro:"Risiko vs imbalan",q:"Ide usaha A: modal Rp30.000, potensi untung Rp20.000, hampir pasti laku. Ide B: modal Rp300.000, potensi untung Rp500.000, tapi belum tentu laku. Penalaran yang sehat untuk pelajar:",options:["Pertimbangkan berapa yang sanggup kamu rugikan tanpa masalah; untuk pemula, mulai dari A (risiko kecil, pelajaran cepat) sebelum mempertaruhkan B","Pilih potensi untung terbesar (B) walau modalnya besar dan kamu belum sanggup menanggung kerugiannya; risiko besar berarti hasil besar dan pelajar perlu berani","Hindari semua risiko dan tak usah memulai usaha; setiap usaha punya kemungkinan merugi, terutama bagi pelajar yang belum berpengalaman"],answer:0,explain:"Ukuran risiko yang tepat bergantung pada kemampuan menanggung kerugian. Pemula belajar lebih baik lewat taruhan kecil yang bisa diulang.",hint:"Apa akibatnya kalau B gagal & Rp300.000 (mungkin pinjaman) hilang?"},
{n:62,type:"tf",micro:"Sebagian besar usaha butuh waktu",q:"Benar atau Salah: Kebanyakan usaha langsung menghasilkan untung besar & stabil sejak minggu pertama; 'sukses instan' adalah hal yang biasa.",answer:false,explain:"Sebaliknya, kebanyakan usaha butuh waktu (bulan hingga tahun) & beberapa kali perbaikan sebelum untungnya stabil. Cerita 'langsung kaya' biasanya menyembunyikan kerja bertahun-tahun, modal, keberuntungan, atau kegagalan sebelumnya.",hint:"Apakah warung/usaha yang sukses di sekitarmu jadi besar dalam semalam?"},
{n:63,type:"mcq",micro:"Etika: bahan & keselamatan",q:"Wirausaha makanan bertanggung jawab untuk...",options:["Menyembunyikan bahan yang berisiko menimbulkan alergi dari pembeli dan membiarkan dagangan tetap laris manis","Menjaga kebersihan, memakai bahan yang aman & tidak kedaluwarsa, & jujur soal isi (mis. alergen) — kesehatan pelanggan di atas untung","Memakai bahan termurah dalam kondisi apa saja, termasuk yang hampir kedaluwarsa, selama pembeli tak langsung sakit di rumah setelah memakannya dan mengeluh"],answer:1,explain:"Keselamatan pelanggan adalah batas yang tidak boleh dilanggar demi untung. Ini juga melindungi usahamu secara hukum & reputasi.",hint:"Apa yang lebih penting daripada untung saat menjual makanan?"},
{n:64,type:"mcq",micro:"Persaingan yang sehat",q:"Cara bersaing yang sehat dengan usaha lain:",options:["Menjelekkan usaha pesaing dengan fitnah yang dibuat-buat dan membuat pelanggan mereka pindah membeli barang darimu saja","Merusak dagangan pesaing diam-diam ketika mereka lengah, dan membuat pelanggan tidak punya pilihan lain selain usahamu","Membuat produk/layananmu lebih baik atau berbeda, & bersikap sportif — bukan menyebar kabar bohong atau merusak barang pesaing"],answer:2,explain:"Persaingan sehat mendorong semua pihak jadi lebih baik & menguntungkan pelanggan. Cara curang melanggar hukum & etika.",hint:"Fokus pada membuat dirimu lebih baik, atau menjatuhkan orang lain?"},
{n:65,type:"tf",micro:"Usaha menciptakan nilai bagi masyarakat",q:"Benar atau Salah: Usaha yang jujur tidak hanya menguntungkan pemiliknya — ia juga menyediakan barang/jasa yang dibutuhkan orang, kadang menciptakan pekerjaan, & menyumbang pajak saat cukup besar.",answer:true,explain:"Kewirausahaan yang sehat adalah mesin penting bagi kesejahteraan bersama, bukan sekadar cara pribadi mencari untung.",hint:"Apa manfaat sebuah warung bagi lingkungan sekitarnya selain untung pemiliknya?"},
{n:66,type:"mcq",micro:"Ketekunan vs menyerah",q:"Setelah usahamu rugi 3 minggu berturut-turut meski sudah diperbaiki, penalaran yang seimbang:",options:["Evaluasi jujur: apakah ada bukti masalahnya bisa diperbaiki (permintaan ada, biaya bisa ditekan), atau tanda kuat ide ini tidak cocok? Tekun pada yang menunjukkan harapan; berani ganti arah kalau data bilang tidak","Lanjutkan usaha bagaimanapun yang terjadi; menyerah berarti kalah dan rugi akan berubah menjadi untung, walau keadaan dan tujuan tiap orang berbeda, dan bertahan adalah satu langkah terbaik","Menyerah setelah gagal sekali saja; kegagalan membuktikan ide usaha itu tak mungkin berhasil dan tidak layak dicoba lagi oleh siapa saja"],answer:0,explain:"Ketekunan berharga, tapi 'ketekunan buta' pada ide yang jelas tidak jalan menghabiskan sumber daya. Baca datanya.",hint:"Kapan tekun itu bijak, & kapan itu keras kepala?"},
{n:67,type:"mcq",micro:"Utang untuk usaha",q:"Meminjam uang untuk modal usaha (terutama jumlah besar) berisiko karena...",options:["Tidak ada risikonya; utang usaha dibayar dari keuntungan dan boleh ditunda tanpa bunga","Utang harus dibayar (dengan bunga) apakah usaha untung atau tidak — kalau usaha gagal, kamu tetap berutang","Utang itu gratis; pemberi pinjaman hanya meminta kembali pokoknya, tanpa bunga dan tanpa batas waktu"],answer:1,explain:"Modal dari tabungan sendiri berisiko lebih rendah. Untuk pelajar, hindari berutang untuk usaha; mulai dari modal kecil yang kamu miliki.",hint:"Apa yang terjadi pada utangmu kalau usaha yang dibiayainya bangkrut?"},
{n:68,type:"tf",micro:"Untung bukan satu-satunya tujuan",q:"Benar atau Salah: Selain untung, wirausaha bisa mengejar tujuan lain — menyelesaikan masalah yang dipedulikan, belajar, memberi manfaat bagi komunitas — & sering tujuan-tujuan ini saling mendukung.",answer:true,explain:"Usaha yang tulus menyelesaikan masalah nyata cenderung menemukan pelanggan setia. Makna & untung tidak selalu bertentangan.",hint:"Bisakah sebuah usaha sekaligus menguntungkan & bermanfaat bagi banyak orang?"},
{n:69,type:"mcq",micro:"Menilai 'peluang usaha' dari orang lain",q:"Seseorang mengajakmu 'bisnis' yang mengharuskan membayar pendaftaran & keuntungan utamanya dari merekrut anggota baru, bukan menjual produk nyata. Ini...",options:["Peluang usaha yang bagus dan aman, jadi sebaiknya segera didaftarkan dan teman-teman diajak ikut bergabung pula","Sama saja dengan usaha biasa yang menjual barang atau jasa, jadi tidak perlu dicurigai maupun dibicarakan dengan orang tua","Ciri skema piramida — berisiko tinggi, sering ilegal, & kebanyakan peserta rugi; tolak & bicarakan dengan orang tua"],answer:2,explain:"Kalau uang datang terutama dari perekrutan & bukan penjualan produk ke pelanggan nyata, itu skema piramida yang merugikan mayoritas peserta.",hint:"Dari mana 'keuntungan' berasal: menjual produk ke pelanggan, atau merekrut orang yang membayar?"},
{n:70,type:"order",micro:"Menanggapi kegagalan usaha",q:"Urutkan cara sehat menanggapi usaha kecil yang gagal.",items:["Hitung kerugian sebenarnya & pastikan kewajiban (mis. ke pemasok/teman) diselesaikan","Tulis apa yang kamu pelajari: apa yang salah, apa yang di luar kendali, apa yang bisa berbeda","Simpan pelajaran & sumber daya yang masih berguna (keterampilan, alat, pelanggan)","Putuskan: perbaiki & coba lagi versi lebih baik, atau alihkan ke ide berbeda"],answer:[0,1,2,3],explain:"Selesaikan kewajiban → petik pelajaran → simpan yang berguna → putuskan langkah berikutnya. Kegagalan yang dikelola baik jadi modal berikutnya.",hint:"Sebelum melcompat ke ide baru, apa yang harus dibereskan & dipelajari?"},
{n:71,type:"mcq",micro:"Dampak harga pada pelanggan",q:"Saat menetapkan harga untuk pelanggan yang sebagian besar teman sebaya dengan uang saku terbatas, pertimbangan tambahan:",options:["Menemukan harga yang menutup biaya & memberi untung wajar TANPA memberatkan teman — kadang berarti porsi/versi lebih kecil & lebih murah","Naikkan harga setinggi mungkin; mereka teman dekatmu dan mau membayar berapa saja demi membantu usahamu, bukan pelanggan biasa yang suka menawar atau membandingkan harga","Jual rugi terus-menerus demi disukai teman-teman; pertemanan lebih penting daripada menutup biaya bahan dan tenagamu"],answer:0,explain:"Memahami kemampuan bayar pasar sasaran menghasilkan harga & produk yang benar-benar cocok — bukan terlalu mahal, bukan merugikan.",hint:"Bagaimana menyeimbangkan untung wajar dengan kondisi kantong teman-teman?"},
{n:72,type:"tf",micro:"Reputasi adalah aset",q:"Benar atau Salah: Reputasi sebuah usaha tidak penting — kebohongan atau produk buruk tidak berpengaruh pada apakah pelanggan kembali.",answer:false,explain:"Sebaliknya, reputasi (dikenal jujur, berkualitas, menepati janji) adalah salah satu aset paling berharga; butuh waktu lama membangunnya tapi bisa rusak cepat oleh satu kebohongan atau kegagalan besar.",hint:"Berapa lama membangun kepercayaan, & berapa cepat kehilangannya?"},
{n:73,type:"mcq",micro:"Menskalakan dengan hati-hati",q:"Setelah usahamu kecilmu untung stabil, memperbesarnya sebaiknya...",options:["Tak memperbesar usaha; usaha harus tetap kecil dan itu lebih aman, tak mengalami kerugian dalam jangka panjang di sekolah","Bertahap & berdasarkan permintaan nyata — tambah kapasitas saat pesanan konsisten melebihi yang bisa kamu penuhi, bukan berdasarkan harapan","Langsung memperbesar sebesar-besarnya dengan memakai semua tabungan; kesempatan tumbuh tidak datang dua kali dalam hidup"],answer:1,explain:"Membesar terlalu cepat (stok, alat, tempat) sebelum permintaan terbukti adalah penyebab umum usaha yang tadinya sehat jadi rugi.",hint:"Perbesar karena permintaan nyata sudah melampaui kapasitas, atau karena berharap akan laku?"},
{n:74,type:"mcq",micro:"Belajar dari usaha lain",q:"Mengamati usaha yang sukses di sekitarmu berguna untuk belajar...",options:["Menyalin persis semuanya, termasuk masalah dan kelemahan mereka; yang sudah berhasil cocok untuk idemu juga, walau konteksnya berbeda","Tak ada yang bisa dipelajari dari orang lain; setiap usaha berhasil hanya karena keberuntungan pemiliknya, jadi lebih baik coba sendiri dari nol tanpa meniru atau mengamati usaha lain","Bagaimana mereka melayani pelanggan, menetapkan harga, menjaga kualitas, & bertahan — lalu menyesuaikan pelajaran itu (bukan menjiplak buta) ke ideamu"],answer:2,explain:"Belajar dari praktik baik orang lain mempercepat pembelajaranmu, asal disesuaikan dengan konteksmu sendiri.",hint:"Apa yang bisa kamu pelajari dari warung favorit di lingkunganmu?"},
{n:75,type:"mcq",micro:"Waktu, sekolah, & usaha",q:"Bagi pelajar, kewirausahaan paling sehat kalau...",options:["Terbatas & terjadwal agar tidak mengganggu belajar & istirahat, & dipandang terutama sebagai sarana belajar keterampilan (mengelola uang, melayani, memecahkan masalah)","Menggantikan sekolah, karena pengalaman berdagang dianggap jauh lebih penting daripada belajar di kelas bagi banyak pelajar yang ingin cepat mandiri","Menghabiskan seluruh waktu luang dan waktu tidur untuk berjualan, supaya usahanya cepat besar sebelum pelajar lulus sekolah"],answer:0,explain:"Nilai terbesar wirausaha pelajar adalah pembelajarannya. Itu hilang kalau mengorbankan pendidikan & kesehatan.",hint:"Apa manfaat utama berwirausaha saat masih sekolah, & apa syaratnya?"},
{n:76,type:"tf",micro:"Menghitung semua biaya termasuk yang tersembunyi",q:"Benar atau Salah: Menghitung biaya bahan saja (mengabaikan transport, listrik, penyusutan alat, sisa bahan, & nilai waktu) sudah cukup untuk mengetahui untung sebenarnya.",answer:false,explain:"Sebaliknya, wirausaha pemula sering terlihat 'untung' padahal rugi karena lupa biaya tersembunyi. Untung sejati hanya terlihat setelah SEMUA biaya dihitung, termasuk yang tidak berupa uang tunai langsung.",hint:"Kalau kamu hanya menghitung biaya bahan & lupa ongkos & alat, apakah 'untung'-mu nyata?"},
{n:77,type:"mcq",micro:"Nilai bagi pelanggan menentukan harga maksimum",q:"Batas ATAS harga yang bisa kamu tetapkan pada dasarnya ditentukan oleh...",options:["Biaya bahan dikali sepuluh, tanpa memandang apa yang dirasakan pelanggan dan harga produk serupa di sekitarmu nanti, serta berapa lama kamu membuatnya","Seberapa besar nilai/manfaat yang dirasakan pelanggan & kemampuan bayarnya — kalau harga melebihi itu, mereka tidak membeli","Keinginanmu untuk untung besar; pelanggan akan membayar berapa saja harga yang kamu tentukan sendiri di pasar"],answer:1,explain:"Biaya menentukan batas BAWAH (jangan jual di bawahnya); nilai bagi pelanggan menentukan batas ATAS. Harga baik ada di antara keduanya.",hint:"Apa yang membuat pelanggan berhenti membeli meski produknya bagus?"},
{n:78,type:"mcq",micro:"Kejujuran saat usaha kesulitan",q:"Usahamu terlambat menyelesaikan pesanan. Sikap yang menjaga kepercayaan:",options:["Diam saja dan berharap pelanggan tidak bertanya; memberi tahu keterlambatan hanya akan membuat mereka marah dan pergi","Berbohong bahwa pesanan 'sedang dalam pengiriman' dan membuat pelanggan menunggu dengan tenang sampai pesanannya benar-benar selesai","Segera beri tahu pelanggan dengan jujur, minta maaf, & tawarkan solusi (waktu baru, potongan, atau pembatalan)"],answer:2,explain:"Komunikasi jujur & cepat saat ada masalah sering menyelamatkan hubungan; kebohongan yang ketahuan menghancurkannya.",hint:"Apa yang lebih kamu hargai dari penjual yang bermasalah: kejujuran cepat atau alasan palsu?"},
{n:79,type:"mcq",micro:"Menimbang saran orang",q:"Banyak orang akan memberi saran tentang usahamu. Sikap bijak:",options:["Dengarkan, tapi timbang berdasarkan bukti & pengalaman pemberi saran serta kecocokan dengan pelanggan & konteksmu — bukan menuruti atau menolak semuanya","Turuti setiap saran yang masuk; orang yang memberi saran lebih berpengalaman darimu, jadi tak perlu ditimbang lagi oleh pemula","Abaikan semua saran; usahamu milik sendiri dan hanya pendapatmu yang boleh dipakai dalam setiap keputusan harian usaha"],answer:0,explain:"Saran bervariasi kualitasnya. Uji saran penting dengan data kecil sebelum mengubah usaha secara besar.",hint:"Bagaimana memilah saran yang berguna dari yang tidak?"},
{n:80,type:"open",micro:"Menilai peluang & etika sebuah ide",q:"Seorang teman mengusulkan kalian berjualan 'PR selesai' — mengerjakan tugas teman lain dengan bayaran. Ia bilang 'ada pasarnya, pasti laku, & itu jasa seperti les'. Analisis: (1) apakah ada 'pasar'-nya & mengapa, (2) apa bedanya dengan les/bimbingan yang sah, (3) dampak & risikonya (bagi pembeli, bagi kalian, bagi kelas), (4) alternatif yang mendekati kebutuhan yang sama tapi etis, (5) kesimpulan & alasanmu.",explain:"Jawaban baik: mengakui ada 'permintaan' tapi memisahkannya dari kelayakan; menjelaskan beda jelas antara membantu belajar (sah) & mengerjakan untuk orang lain (kecurangan); menguraikan dampak pada pembeli, penjual, & kelas; menawarkan alternatif etis yang memenuhi kebutuhan sebenarnya (kesulitan memahami); & menyimpulkan menolak dengan alasan etika & kepentingan jangka panjang.",hint:"'Ada pasarnya' ≠ 'layak dijual'. Bandingkan membantu orang belajar vs menggantikan usaha mereka; pikirkan dampak jangka panjang & keadilan.",sample:"(1) Ada 'permintaan' karena sebagian teman ingin nilai tanpa usaha atau kewalahan — tapi adanya permintaan tidak membuat sesuatu layak dijual. (2) Les/bimbingan yang sah MEMBANTU teman memahami & mengerjakan sendiri (menjelaskan konsep, memeriksa, memberi latihan); 'menjual PR selesai' menggantikan pekerjaan mereka — itu membantu mereka menipu guru & tidak belajar. (3) Dampak: pembeli tidak menguasai materi & akan kesulitan saat ujian (yang dikerjakan sendiri) — nilai jangka panjangnya turun; bagi kami, ini pelanggaran kejujuran akademik yang bisa berujung sanksi sekolah & rusaknya reputasi; bagi kelas, ini tidak adil bagi yang mengerjakan sendiri & merusak kepercayaan guru. (4) Alternatif etis: buka jasa 'teman belajar' — sesi menjelaskan materi & menemani mengerjakan (bukan mengerjakan untuk mereka), membuat ringkasan/latihan soal, atau kelompok belajar berbayar tipis. Ini memenuhi kebutuhan nyata (kesulitan memahami, butuh teman belajar) tanpa kecurangan. (5) Kesimpulan: tolak ide 'menjual PR selesai' — ada permintaan bukan berarti etis atau baik; ia merugikan pembeli (tidak belajar), berisiko sanksi, & merusak keadilan kelas. Alihkan ke jasa bimbingan yang membantu teman belajar sendiri."},
{n:81,type:"mcq",micro:"Peta: dari ide ke usaha",q:"Ringkasan alur kewirausahaan:",options:["Jual apa saja yang sedang laku dengan klaim menarik, tanpa menghitung biaya, tanpa mencatat, dan tanpa mendengar pelanggan, lalu naikkan harga sampai untung terlihat besar, dan berutang bila modal kurang demi memperbesar usaha secepatnya","Temukan masalah nyata & pelanggan → rancang produk/jasa → hitung biaya & tetapkan harga di antara biaya dan nilai pelanggan → uji kecil, catat, hitung untung & titik impas → perbaiki dari umpan balik → reinvestasi & skalakan bertahap","Punya ide keren lalu langsung berutang besar untuk produksi massal tanpa uji coba, dan berharap pelanggan datang sendiri setelah produk jadi; semua pengeluaran akan tertutup oleh penjualan pertama, tanpa perlu umpan balik"],answer:1,explain:"Masalah & pelanggan → produk & pembeda → biaya & harga → uji & ukur → perbaiki → reinvestasi & skalakan. Selalu berbasis bukti.",hint:"Gabungkan: masalah/pelanggan + produk/pembeda + biaya/harga + uji/ukur + perbaiki + skalakan."},
{n:82,type:"mcq",micro:"Peta: uang dalam usaha",q:"Ringkasan konsep keuangan usaha:",options:["Pendapatan yang besar berarti untung yang besar pula; biaya, arus kas, dan titik impas tak perlu dihitung oleh pemilik usaha, dan usaha lain mengalami hal serupa dan tak perlu dicatat","Yang penting hanya biaya bahan baku saja; biaya tenaga, kemasan, dan transport boleh diabaikan, dan untung sama dengan arus kas tunai","Pendapatan (omzet) = uang masuk dari penjualan; biaya = tetap + variabel; untung = pendapatan − semua biaya; titik impas = biaya tetap ÷ untung per unit; arus kas (tunai yang ada) berbeda dari untung — usaha butuh keduanya sehat"],answer:2,explain:"Pendapatan ≠ untung; biaya ada dua jenis; titik impas menargetkan penjualan minimal; arus kas ≠ untung.",hint:"Gabungkan: pendapatan, biaya (tetap+variabel), untung, titik impas, arus kas."},
{n:83,type:"tf",micro:"Wirausaha butuh literasi keuangan",q:"Benar atau Salah: Kewirausahaan menggabungkan hampir semua keterampilan keuangan lain — memahami penghasilan & biaya, menganggarkan, menabung/reinvestasi, mengelola risiko, & kadang meminjam.",answer:true,explain:"Menjalankan usaha adalah 'latihan terpadu' literasi keuangan. Karena itu ia mengajarkan banyak hal sekaligus.",hint:"Berapa banyak keterampilan keuangan yang dipakai saat menjalankan usaha kecil?"},
{n:84,type:"mcq",micro:"Kesalahan pemula paling umum",q:"Kesalahan yang paling sering membuat usaha pelajar rugi:",options:["Tidak menghitung semua biaya (termasuk tersembunyi), menetapkan harga terlalu murah, memproduksi lebih dari permintaan, & mencampur uang usaha dengan uang jajan","Terlalu berhati-hati dalam setiap langkah, hingga usaha tak berani menjual kepada pelanggan baru dan penjualan menurun terus","Terlalu banyak mencatat pemasukan dan pengeluaran, hingga waktu berjualan berkurang dan usaha sering merugi di akhir bulan"],answer:0,explain:"Empat jebakan klasik: biaya tidak lengkap, harga terlalu rendah, kelebihan produksi, & keuangan tercampur. Menghindarinya sudah sangat membantu.",hint:"Apa saja hal yang membuat 'terasa untung' padahal rugi?"},
{n:85,type:"order",micro:"Menjalankan siklus usaha satu putaran",q:"Urutkan satu putaran penuh menjalankan usaha kecil.",items:["Tetapkan ide, pelanggan sasaran, & pembeda","Hitung biaya tetap & variabel, tetapkan harga, & hitung titik impas","Produksi kecil sesuai perkiraan permintaan, jual, & catat semua pemasukan & pengeluaran","Hitung untung nyata, kumpulkan umpan balik, ubah satu hal, & tentukan lanjut/perbesar/hentikan"],answer:[0,1,2,3],explain:"Ide & pelanggan → biaya, harga, titik impas → produksi kecil, jual, catat → hitung, dengarkan, sesuaikan, putuskan.",hint:"Tiap putaran: rencana → angka → jual & catat → evaluasi & sesuaikan."},
{n:86,type:"mcq",micro:"Etika kewirausahaan",q:"Batas etika yang tidak boleh dilanggar demi untung:",options:["Hanya tidak boleh mencuri; selain itu semua cara boleh, termasuk berbohong tentang produk dan merusak dagangan pesaing","Kejujuran (klaim & kualitas), keselamatan pelanggan, menepati janji, persaingan sportif, & mematuhi aturan yang melindungi orang","Tak ada batas asalkan menghasilkan untung; tujuan utama usaha adalah uang, bukan kejujuran maupun keselamatan"],answer:1,explain:"Untung yang diperoleh dengan membohongi, membahayakan, atau mencurangi orang bukan keberhasilan sejati & tidak berkelanjutan.",hint:"Apa yang lebih penting daripada untung dalam berjualan?"},
{n:87,type:"tf",micro:"Gagal kecil lebih baik daripada gagal besar",q:"Benar atau Salah: Menguji ide usaha dengan skala kecil & murah lebih bijak daripada langsung besar, karena kalau gagal, kerugiannya terbatas & pelajarannya tetap didapat.",answer:true,explain:"'Taruhan kecil yang bisa diulang' adalah cara pemula belajar berwirausaha dengan risiko terkendali.",hint:"Rugi Rp30.000 dari uji kecil, atau rugi Rp3 juta dari peluncuran besar yang gagal?"},
{n:88,type:"mcq",micro:"Menutup: kewirausahaan",q:"Sikap paling berguna tentang kewirausahaan:",options:["Cari ide yang bisa membuatmu cepat kaya, lalu jual dengan klaim yang membuat orang membeli tanpa memikirkan akibatnya, dan utang besar tak jadi soal selama pelanggan banyak, serta pesaing harus disingkirkan dengan cara apa saja","Kewirausahaan terlalu berisiko bagi pelajar, jadi jangan dicoba; cukup menunggu sampai dewasa dan mendapat pekerjaan tetap; belajar usaha hanya bisa dilakukan setelah lulus kuliah dan punya modal besar sendiri","Lihat masalah orang sebagai peluang menciptakan nilai; hitung biaya & untung dengan jujur; uji kecil lalu perbaiki dari umpan balik; jaga kejujuran, kualitas, & keselamatan; skalakan bertahap; anggap kegagalan kecil sebagai pelajaran"],answer:2,explain:"Inti: nilai bagi orang lain + hitungan jujur + uji & perbaiki + etika sebagai batas + tumbuh bertahap + belajar dari gagal.",hint:"Gabungkan: nilai + hitungan jujur + uji & perbaiki + etika + tumbuh bertahap + belajar dari gagal."},
{n:89,type:"mcq",micro:"Ringkasan: kewirausahaan",q:"Rangkuman paling tepat:",options:["Wirausaha menciptakan nilai dengan memecahkan masalah orang & menanggung risikonya; keberhasilan bergantung pada eksekusi, bukan sekadar ide; keuangannya dipahami lewat biaya, untung, titik impas, & arus kas; ide diuji kecil & diperbaiki","Kewirausahaan adalah punya ide bagus lalu menunggu sampai kaya; eksekusi, penghitungan biaya, dan umpan balik tak penting, ide hebat laku sendiri; ide tak perlu diuji kecil; untung terbesar dicapai dengan menekan kualitas","Yang penting hanya pendapatan sebesar-besarnya; untung, biaya, titik impas, dan arus kas tak perlu dihitung selama uang masuk; ide cukup diluncurkan besar-besaran; umpan balik dianggap gangguan; kejujuran boleh dikorbankan"],answer:0,explain:"Menciptakan nilai + eksekusi + keuangan (pendapatan/biaya/untung/titik impas/arus kas) + uji & perbaiki + etika & pertumbuhan bertahap = inti.",hint:"Gabungkan: nilai & risiko + eksekusi + keuangan usaha + uji & perbaiki + etika & tumbuh bertahap."},
{n:90,type:"tf",micro:"Kewirausahaan bisa dipelajari",q:"Benar atau Salah: Kewirausahaan adalah bakat bawaan lahir yang hanya dimiliki segelintir orang & tidak bisa dilatih.",answer:false,explain:"Sebaliknya, kewirausahaan sebagian besar keterampilan yang bisa dipelajari (mengenali masalah, menghitung, menjual, memperbaiki) & tumbuh lewat latihan, kegagalan kecil, & refleksi. Memulai dari usaha pelajar kecil adalah latihan yang baik.",hint:"Apakah kemampuan menghitung untung & melayani pelanggan bisa dilatih?"},
{n:91,type:"mcq",micro:"Tiga prinsip praktis",q:"Tiga prinsip praktis kewirausahaan:",options:["Jangan mencatat, jangan menghitung biaya, dan jangan mendengarkan pelanggan; usaha yang baik berjalan lancar tanpa perhatian dan banyak orang mengalami hal serupa, jadi cukup ditunggu hasilnya nanti","Mulai dari masalah nyata & uji kecil sebelum besar; hitung SEMUA biaya & pastikan harga menutupnya + memberi untung + masih masuk akal bagi pelanggan; & jaga kejujuran, kualitas, & keselamatan sebagai batas yang tidak dilanggar demi untung","Cari ide paling unik, berutang besar untuk memulainya, dan jual dengan klaim yang membuat orang tertarik membeli, walau klaimnya belum teruji dan belum pernah dicoba pelanggan"],answer:1,explain:"Uji kecil + hitungan biaya-harga yang benar + etika sebagai batas = inti praktis.",hint:"Gabungkan: uji kecil + hitung semua biaya & harga yang benar + kejujuran/kualitas/keselamatan."},
{n:92,type:"open",micro:"Kapstone: jalankan & analisis usaha mini",q:"Rancang usaha mini nyata yang bisa kamu jalankan dalam 2 minggu, lalu buat rencana analisisnya. Sertakan: (1) masalah, pelanggan sasaran, & pembeda, (2) daftar lengkap biaya (tetap & variabel, termasuk biaya tersembunyi & nilai waktumu), (3) harga jual + alasan, (4) untung per unit, titik impas, & target penjualan 2 minggu, (5) rencana pencatatan, (6) 3 pertanyaan umpan balik, (7) kriteria terukur untuk 'lanjut & perbesar' vs 'perbaiki' vs 'hentikan', (8) rencana pembagian untung, (9) satu risiko utama + mitigasi, (10) satu batas etika.",explain:"Kapstone lengkap menutup kesepuluh poin dengan angka yang konsisten: masalah & pelanggan & pembeda jelas; biaya lengkap termasuk tersembunyi & nilai waktu; harga diposisikan dengan alasan di antara biaya & nilai; untung per unit & titik impas & target dihitung; rencana pencatatan konkret; pertanyaan umpan balik berguna; kriteria lanjut/perbaiki/hentikan terukur; pembagian untung dengan reinvestasi; risiko + mitigasi nyata; & batas etika eksplisit.",hint:"Kerjakan kesepuluh poin; pastikan biaya → harga → untung per unit → titik impas → target saling konsisten, & kriteria keputusan bisa diukur dengan angka.",sample:"Contoh (usaha: 'jasa bungkus kado + kartu ucapan' untuk teman yang mau memberi hadiah ulang tahun): (1) Masalah: teman punya hadiah tapi tidak bisa/tidak sempat membungkus rapi & bingung menulis kartu; pelanggan: teman seangkatan yang sering ikut patungan kado; pembeda: rapi, cepat (jadi di hari yang sama), & termasuk kartu tulisan tangan yang bagus. (2) Biaya variabel/kado: kertas kado Rp2.000 + pita Rp1.000 + kartu Rp1.000 + selotip/lem (bagian) Rp300 = Rp4.300. Biaya tetap: gunting & penggaris (sudah punya, tapi kuhitung penyusutan Rp5.000 untuk 2 minggu), contoh display Rp5.000 = Rp10.000. Biaya tersembunyi: waktu ~15 menit/kado; kuhargai waktuku ~Rp8.000/jam → ~Rp2.000/kado. (3) Harga jual: Rp10.000/kado. Alasan: menutup biaya bahan (Rp4.300) + nilai waktu (Rp2.000) + kontribusi ke biaya tetap & untung; membeli kertas+pita+kartu sendiri & membungkus rapi biasanya lebih mahal & merepotkan, jadi Rp10.000 terasa sepadan bagi pelanggan. (4) Untung per unit (di luar nilai waktu, sebagai kas) = Rp10.000 − Rp4.300 = Rp5.700. Kalau nilai waktu dihitung: Rp3.700. Titik impas (kas, atas biaya tetap Rp10.000) = Rp10.000 ÷ Rp5.700 ≈ 2 kado. Target 2 minggu: 15 kado. (5) Pencatatan: buku kecil / catatan HP dengan kolom tanggal, jumlah kado, uang masuk, bahan terpakai, biaya, & catatan umpan balik; direkap tiap akhir pekan. (6) Umpan balik: 'Harganya pas/mahal/murah?', 'Hasilnya serapi harapanmu?', 'Kamu mau pakai lagi & merekomendasikan?'. (7) Lanjut & perbesar kalau ≥12 kado terjual & ada permintaan berulang → tambah stok kertas & varian. Perbaiki kalau 6–11 terjual → tinjau harga/kualitas/promosi, ubah satu hal. Hentikan kalau ≤5 terjual & umpan balik 'tidak butuh'. (8) Pembagian untung: 50% beli bahan berikutnya, 25% tabungan usaha (beli gunting/alat lebih baik), 25% kunikmati. (9) Risiko utama: sisa kertas kado tidak terpakai kalau sepi → mitigasi: beli kertas secukupnya per gelombang pesanan, terima pesanan H-1, mulai dari stok untuk 8 kado. (10) Batas etika: harga kuumumkan jelas di depan (tidak ada biaya tersembunyi), & kalau hasil bungkusku kurang rapi karena kesalahanku, kuperbaiki gratis atau kukembalikan sebagian uang."},
{n:93,type:"mcq",micro:"Menilai sebuah keputusan wirausaha",q:"Keputusan wirausaha yang layak dipuji...",options:["Mengejar untung terbesar secepat mungkin dengan cara apa saja, termasuk mengurangi kualitas dan menyembunyikan kekurangan dari pelanggan demi cepat berkembang","Bertahan pada rencana awal bagaimanapun hasilnya, tanpa mau mendengar umpan balik atau melihat catatan penjualan yang ada","Berdasar pada data (pencatatan, umpan balik) & hitungan biaya yang jujur & lengkap; menguji perubahan kecil sebelum besar; menjaga kejujuran & keselamatan; & tumbuh sesuai permintaan nyata"],answer:2,explain:"Keputusan wirausaha yang baik berbasis bukti, beretika, & bertahap — bukan nekat atau keras kepala.",hint:"Apa ciri keputusan usaha yang bijak?"},
{n:94,type:"mcq",micro:"Kewirausahaan & dampak sosial",q:"Kewirausahaan yang sehat berkontribusi pada masyarakat dengan...",options:["Menyediakan barang/jasa yang dibutuhkan, menciptakan pekerjaan saat tumbuh, mendorong inovasi & persaingan yang menguntungkan pelanggan, & menyumbang pajak","Hanya memperkaya pemiliknya, tanpa manfaat lain; barang dan jasa yang dijual tak dibutuhkan orang lain dan tak menambah pekerjaan","Merugikan masyarakat; persaingan dan keuntungan membuat orang lain jatuh miskin dan kehilangan pekerjaan di sekitarnya"],answer:0,explain:"Usaha yang jujur adalah bagian penting dari ekonomi yang melayani banyak orang, bukan sekadar alat pribadi.",hint:"Apa manfaat usaha-usaha kecil bagi lingkungan & ekonomi sekitarmu?"},
{n:95,type:"tf",micro:"Untung sejati butuh hitungan lengkap",q:"Benar atau Salah: Sebuah usaha baru bisa disebut benar-benar untung setelah SEMUA biaya diperhitungkan — bahan, biaya tetap, biaya tersembunyi (transport, alat, sisa bahan), & sewajarnya nilai waktu yang dicurahkan.",answer:true,explain:"'Untung' yang mengabaikan biaya tersembunyi & waktu sering ilusi. Hitungan lengkap memberi gambaran sebenarnya.",hint:"Apakah 'untung' yang lupa menghitung ongkos & waktu benar-benar untung?"},
{n:96,type:"mcq",micro:"Kegagalan & pertumbuhan",q:"Cara pandang produktif terhadap kegagalan usaha kecil:",options:["Sesuatu yang harus disembunyikan dan tidak boleh dipikirkan lagi, hingga tidak mengganggu semangat untuk memulai usaha yang baru","Sumber pelajaran spesifik (apa yang salah, apa di luar kendali, apa yang akan dilakukan berbeda) yang membuat percobaan berikutnya lebih baik — asal kewajiban diselesaikan & kerugian terbatas","Bukti bahwa kamu tidak berbakat dan harus berhenti berwirausaha; orang yang gagal sekali tak akan berhasil bagi banyak orang pada akhirnya, lebih baik jadi pegawai"],answer:1,explain:"Wirausaha berpengalaman memandang kegagalan kecil sebagai biaya pembelajaran — selama dikelola & dievaluasi.",hint:"Apa yang membuat kegagalan jadi berharga alih-alih sekadar rugi?"},
{n:97,type:"mcq",micro:"Inti yang dibawa pulang",q:"Satu gagasan inti tentang kewirausahaan:",options:["Kewirausahaan adalah bakat langka yang hanya dimiliki segelintir orang sejak lahir untuk cepat kaya, jadi tak bisa dipelajari atau dilatih oleh pelajar maupun orang dewasa mana pun, termasuk lewat latihan di sekolah","Kewirausahaan hanya soal punya ide yang unik; biaya, harga, umpan balik, dan etika tak berpengaruh, dan kegagalan kecil berarti usaha harus dihentikan; pelajar sebaiknya fokus belajar saja tanpa mencoba usaha sendiri","Kewirausahaan adalah keterampilan yang dipelajari: melihat masalah orang sebagai peluang, menciptakan nilai, menghitung untung dengan jujur, menguji kecil & memperbaiki dari umpan balik, & tumbuh etis — kegagalan kecil bagian dari belajar"],answer:2,explain:"Keterampilan yang dipelajari + nilai nyata + hitungan jujur + uji & perbaiki + tumbuh etis & bertahap + belajar dari gagal = inti.",hint:"Gabungkan: keterampilan yang dipelajari + nilai nyata + hitungan jujur + uji & perbaiki + tumbuh etis."},
{n:98,type:"mcq",micro:"Menghubungkan ke keterampilan lain",q:"Kewirausahaan memperkuat keterampilan keuangan lain karena...",options:["Menjalankan usaha melatih sekaligus: memahami penghasilan & biaya, menganggarkan, memisahkan kebutuhan-keinginan, menabung & reinvestasi, mengelola risiko, & berpikir tentang nilai & harga","Tak berhubungan dengan keterampilan keuangan lain; berjualan kegiatan sendiri yang berbeda dengan menabung, menganggarkan, dan mengelola risiko uang pribadi","Hanya mengajarkan cara menjual dan merayu pembeli, sedangkan memahami biaya, menganggarkan, menabung, dan mengelola risiko tidak dipelajari dari berusaha"],answer:0,explain:"Usaha kecil adalah 'laboratorium' terpadu untuk hampir semua konsep literasi keuangan.",hint:"Berapa banyak keterampilan keuangan yang dilatih sekaligus saat menjalankan usaha?"},
{n:99,type:"tf",micro:"Wirausaha pelajar: alat belajar",q:"Benar atau Salah: Bagi pelajar, satu-satunya hal yang berharga dari berwirausaha adalah besarnya uang yang dihasilkan; keterampilan & pemahaman yang didapat tidak penting.",answer:false,explain:"Sebaliknya, nilai terbesar wirausaha pelajar (dalam batas yang tidak mengganggu sekolah) adalah keterampilannya — mengelola uang, melayani orang, memecahkan masalah, menghadapi kegagalan — bekal yang jauh melebihi untung kecilnya.",hint:"Apa yang lebih berharga dari usaha pertamamu: untung Rp50.000, atau pelajaran menjalankannya?"},
{n:100,type:"open",micro:"Kapstone: panduan 'Kewirausahaan' untuk teman sebaya",q:"Tulis panduan singkat (8–10 poin) berjudul 'Kewirausahaan: Ide, Biaya & Untung untuk Pemula' untuk teman sebayamu. Cakup: ide dari masalah nyata, mengenal pelanggan & pembeda, biaya tetap vs variabel & biaya tersembunyi, untung = pendapatan − semua biaya, menetapkan harga (di antara biaya & nilai), titik impas, uji kecil & perbaiki dari umpan balik, memisahkan uang usaha & pribadi + mencatat, reinvestasi sebagian untung & tumbuh bertahap, etika (jujur, kualitas, keselamatan), waspada skema piramida, & kegagalan sebagai pelajaran. Gunakan bahasa jelas & contoh.",explain:"Panduan baik menyederhanakan semua konsep inti: ide dari masalah, pelanggan & pembeda, jenis biaya + biaya tersembunyi, untung = pendapatan − semua biaya, penetapan harga di antara biaya & nilai, titik impas sebagai target, uji kecil + catat + perbaiki dari umpan balik (satu perubahan), pisahkan & catat keuangan, reinvestasi & tumbuh bertahap, etika sebagai batas, waspada skema piramida, & kegagalan sebagai pelajaran — dengan bahasa & contoh ramah sebaya.",hint:"Tiap poin harus jelas, benar, & langsung berguna untuk teman yang mau mencoba usaha kecil pertamanya.",sample:"Contoh panduan: 1) Ide usaha yang baik menjawab MASALAH NYATA orang ('teman lapar saat istirahat', 'lupa bawa alat tulis'). Tanya: 'Apa yang menyusahkan orang di sekitarku & bisa kubantu?' 2) Kenali PELANGGAN sasaranmu (siapa yang paling butuh & mampu bayar) & PEMBEDA-mu (kenapa mereka pilih kamu, bukan penjual lain: lebih enak/murah/cepat/ramah/dekat). 3) Ada dua jenis biaya: TETAP (sewa, spanduk — tidak berubah dengan jumlah terjual) & VARIABEL (bahan, kemasan per unit). Jangan lupa BIAYA TERSEMBUNYI: transport, listrik, alat yang aus, bahan terbuang, & waktumu sendiri. 4) UNTUNG = pendapatan − SEMUA biaya. Pendapatan besar belum tentu untung — biaya bisa memakannya. 5) HARGA jual harus di atas biaya per unit (kalau tidak, tiap penjualan menambah rugi) tapi tidak melebihi NILAI yang dirasakan pelanggan (kalau tidak, tidak ada yang beli). Cari di antaranya. 6) TITIK IMPAS = biaya tetap ÷ untung per unit = berapa unit yang harus terjual agar tidak rugi. Jadikan target minimal. 7) UJI KECIL dulu (sedikit produk, lingkungan terdekat), CATAT semuanya, lalu perbaiki dari UMPAN BALIK pelanggan — ubah SATU hal per kali agar tahu mana yang berpengaruh. 8) PISAHKAN uang usaha & uang jajan, & catat tiap pemasukan & pengeluaran — tanpa catatan, 'untung' cuma perasaan. 9) Sisihkan sebagian untung untuk MODAL berikutnya & tabungan usaha (jangan habiskan semua); PERBESAR usaha bertahap, hanya saat permintaan nyata melebihi kapasitasmu. 10) ETIKA adalah batas: jujur soal produk, jaga kualitas & keselamatan (apalagi makanan), tepati janji, bersaing sportif. 11) WASPADA 'bisnis' yang untungnya dari merekrut orang yang membayar, bukan menjual produk nyata — itu skema piramida; tolak & bicara dengan orang tua. 12) GAGAL itu wajar & berguna kalau kecil & dievaluasi: selesaikan kewajiban, tulis pelajarannya, coba lagi versi lebih baik atau ganti ide."},
];
